Rect	EQU $08	; Rect - CtlRec - Enclosing rectangle.octlFlag	EQU $10	; Byte - CtlRec - Bit flags.octlHilite	EQU $11	; Byte - CtlRec - Highlighted part.octlValue	EQU $12	; Integer - CtlRec - Control's value.octlProc	EQU $14	; Pointer - CtlRec - Control's definition procedure.octlAction	EQU $18	; Pointer - CtlRec - Control's action procedure.octlData	EQU $1C	; Longint - CtlRec - Reserved for CtrlProc's use.octlRefCon	EQU $20	; Longint - CtlRec - Reserved for application's use.octlColor	EQU $24	; Pointer - CtlRec - Pointer to appropriate color table.oboundRect	EQU $00	; Rect - LimitBlk -	Drag bounds.oslopRect	EQU $08	; Rect - LimitBlk -	Cursor bounds.oaxisParam	EQU $10	; Word - LimitBlk -	Movement constrains.odragPatt	EQU $12	; Pointer - LimitBlk - Pointer to 32 byte Pattern for drag outline.noConstraint	EQU $0000	; Axis Parameter - No constraint on movement.hAxisOnly	EQU $0001	; Axis Parameter - Horizontal axis only.vAxisOnly	EQU $0002	; Axis Parameter - Vertical axis only.simpRound	EQU $0000	; CtlFlag - Simple button flagupFlag	EQU $0001	; CtlFlag - Scroll bar flag. boldButton	EQU $0001	; CtlFlag - Bold round cornered outlined button.simpBRound	EQU $0001	; CtlFlag - Simple button flagdownFlag	EQU $0002	; CtlFlag - Scroll bar flag.simpSquare	EQU $0002	; CtlFlag - Simple button flagsimpDropSquare	EQU $0003	; CtlFlag - Simple button flagleftFlag	EQU $0004	; CtlFlag - Scroll bar flag.rightFlag	EQU $0008	; CtlFlag - Scroll bar flag.dirScroll	EQU $0010	; CtlFlag - Scroll bar flag.horScroll	EQU $0010	; CtlFlag - Scroll bar flag.family	EQU $007F	; CtlFlag - Mask for radio button family numberpartOfExtendedList	equ $0040	; CtlFlag - Scroll bar flag (added 9-Dec-91 DAL)ctlInVis	EQU $0080	; CtlFlag - invisible mask for any type	of control simpleProc	EQU $00000000	; CtlProc -  checkProc	EQU $02000000	; CtlProc -  radioProc	EQU $04000000	; CtlProc -  scrollProc	EQU $06000000	; CtlProc -  growProc	EQU $08000000	; CtlProc -  drawCtl	EQU $0000	; DefProc - Draw control command.calcCRect	EQU $0001	; DefProc - Compute	drag RECT command.testCtl	EQU $0002	; DefProc - Hit test command.initCtl	EQU $0003	; DefProc - Initialize command.dispCtl	EQU $0004	; DefProc - Dispose	command.posCtl	EQU $0005	; DefProc - Move indicator command.thumbCtl	EQU $0006	; DefProc - Compute	drag parameters command.dragCtl	EQU $0007	; DefProc - Drag command.autoTrack	EQU $0008	; DefProc - Action command.newValue	EQU $0009	; DefProc - Set new	value command.setParams	EQU $000A	; DefProc - Set new	parameters command.moveCtl	EQU $000B	; DefProc - Move command.recSize	EQU $000C	; DefProc - Return record size command.noHilite	EQU $0000	; hiliteState - Param to HiliteControlinactiveHilite	EQU $00FF	; hiliteState - Param to HiliteControlnoPart	EQU $0000	; PartCode -  simpleButton	EQU $0002	; PartCode -  checkBox	EQU $0003	; PartCode -  radioButton	EQU $0004	; PartCode -  upArrow	EQU $0005	; PartCode -  downArrow	EQU $0006	; PartCode -  pageUp	EQU $0007	; PartCode -  pageDown	EQU $0008	; PartCode -  growBox	EQU $000A	; PartCode -  thumb	EQU $0081	; PartCode -  ; PartCode -  ;-----------------------------------------------------------;; New stuff for super controls;-----------------------------------------------------------;; Equates for Control TypessimpleButtonControl	equ  $80000000checkControl	equ  $82000000radioControl	equ  $84000000scrollBarControl	equ  $86000000growControl	equ  $88000000statTextControl	equ  $81000000LineEditControl	equ  $83000000TextEditControl	equ  $85000000popUpControl	equ  $87000000listControl	equ  $89000000iconButtonControl	equ  $07FF0001pictureControl	equ  $8D000000;-----------------------------------------------------------;; New action messages supported by some controls;ctlHandleEvent	equ  13	;Send the event record to controlctlChangeActivity	equ  14	;The activity bit in MoreFlags just changed.ctlChangeBounds	equ  15ctlWindChangeSize   equ  16ctlHandleTab	equ  17ctlNotifyMultiPart	equ  18	;Called if set and when HideControl is calledctlWinStateChange	equ  19	;Called if window state changes.;-----------------------------------------------------------;; Old Error codes for control manager.;wmNotStartedUp	equ  $1001	; window mgr. not started first error;-----------------------------------------------------------;; New Error codes for control manager.;NoCtlError	equ $1004	;no controls in windowNoSuperCtlError 	equ $1005	;no super controls in windowNoCtlTargetError	equ $1006	;no Target super controlNotSuperCtlError	equ $1007	;action can only be done on super controlCanNotBeTargetError	equ $1008	;This control cannot be made TargetNoSuchIDError	equ $1009	;The specified ID cannot be foundTooFewParmsError	equ $100A	;there were not enough parameters specified.NoCtlToBeTargetError equ $100B	;Tried to make next ctl Target, but no ctls could be Target.;-----------------------------------------------------------;; MoreFlags Bit Definitions;FCtlTarget	equ  $8000FCtlCanBeTarget	equ  $4000FCtlWantEvents	equ  $2000FCtlProcRefNotPtr	equ  $1000FctlTellAboutSize	equ  $0800TitleVerbMask	equ  %00000011ColorTableVerbMask	equ  %00001100IVVerbMask	equ  %00000011TitleIsPtr	equ  0TitleIsHandle	equ  1TitleIsResource	equ  2TitleIsOffset	equ  3ColorTableIsPtr	 equ  %00000000ColorTableIsHandle	 equ  %00000100ColorTableIsResource equ  %00001000ColorTableIsOffset	 equ  %00001100IVIsPtr	equ  0IVIsHandle	equ  1IVIsResource	equ  2IVIsOffset	equ  3;-----------------------------------------------------------;; Flag bit definitions for StatText Controls;fJustDrawFast	equ  $0004	; Bit set to just call DrawString instead of LETextBox2 (DAL)FSubstituteText	equ  $0002	; Bit is set to indicate that text must be substitutedFSubTextType	equ  $0001	; Bit is set to indicate PStrings, clear for Cstrings		;  (bit is sent to compile text as is.);---------------------------------------------------------------; these are the verbs that NewControl2 supports:;---------------------------------------------------------------singlePtr	equ  0singleHandle	equ  1singleResource	equ  2ptrToPtr	equ  3ptrToHandle	equ  4ptrToResource	equ  5handleToPtr	equ  6handleToHandle	equ  7handleToResource	equ  8resourceToResource	equ  9NewCtlRecord	RECORD  0;---------------------------------------------------------------ctlNext	ds.l  1ctlOwner	ds.l  1ctlRect	ds.w  4ctlFlag	ds.b  1ctlHilite	ds.b  1ctlValue	ds.w  1ctlProc	ds.l  1ctlAction	ds.l  1ctlData	ds.l  1ctlRefCon	ds.l  1ctlColor	ds.l  1ctlReserved	ds.b  16ctlID	ds.l  1ctlMoreFlags	ds.w  1ctlVersion	ds.w  1ctlOptionalDataRecordSize;---------------------------------------------------------------; Values kept in ctlReserved by various controls;---------------------------------------------------------------;; Button Controls;ctlKey1	equ ctlReservedctlKey2	equ ctlKey1+1ctlKeyMods	equ ctlKey2+1ctlKeyModsCareBits	equ ctlKeyMods+2;; StatText Controls;ctlJust	equ ctlReserved	ENDRMINTEMPLATEPCOUNT	equ 6;-----------------------------------------------------------;; This is the generic template record.  All templates have; these fields in them.;TemplateRecord	RECORD  0pCount	ds.w  1	;parameter count (must be at least 6)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;Ref to DefProc, determines control typeFlags	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application definedRecordSize	ENDR;-----------------------------------------------------------;; This is the generic template record.  All templates have; these fields in them.;CustomTemplate	RECORD  0pCount	ds.w  1	;parameter count (must be at least 8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;Ref to DefProc, determines control typeFlags	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application defineddefProcDATA	ds.b  1RecordSize	ENDR;-----------------------------------------------------------;; This is the template for simpleButtonControl.;simpleButtonTemplate RECORD  0pCount	ds.w  1	;parameter count (7 or 8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;simpleButtonControl = $80000000Flag	ds.w  1	;low 2 bits refer to button typeMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.l  1	;Pointer, Handle, resourceID, or OffsetColorTableRef	ds.l  1	;Optional Pointer, Handle, resourceID, or OffsetKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.RecordSize	ENDR;-----------------------------------------------------------;; This is the template for checkControl.;checkTemplate 	RECORD  0pCount	ds.w  1	;parameter count (8 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;checkControl = $82000000Flag	ds.w  1	;nothing specialMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.l  1	;Pointer, Handle, resourceID, or OffsetValue	ds.w  1	;Initial state of check boxColorTableRef	ds.l  1	;Optional Pointer, Handle, resourceID, or OffsetKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.RecordSize	ENDR;-----------------------------------------------------------;; This is the template for radioControl.;radioTemplate	RECORD  0pCount	ds.w  1	;parameter count (8 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;radioControl = $84000000Flag	ds.w  1	;bits 0-6 are family numberMoreFlags	ds.w  1	;bits 0-3 refer to titleref and colortable refRefCon	ds.l  1	;application definedTitleRef	ds.l  1	;Pointer, Handle, resourceID, or OffsetValue	ds.w  1	;Initial state of radio buttonColorTableRef	ds.l  1	;Pointer, Handle, resourceID, or OffsetKey1	ds.b  1	;Optional key equivalentKey2	ds.b  1	;Optional key equivalentKeyMods	ds.w  1	;Required modifiersKeyModsCareBits	ds.w  1	;Mask indicating which mods matter.RecordSize	ENDR;-----------------------------------------------------------;; This is the template for statTextControl.;StatTextTemplate	RECORD  0pCount	ds.w  1	;parameter count (7 or 8)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;StatTextControl = $81000000Flag	ds.w  1	;low 2 bits refer to TextRefMoreFlags	ds.w  1	;must be 0RefCon	ds.l  1	;application definedTextRef	ds.l  1	;Pointer, Handle, resourceID, or OffsetTextSize	ds.w  1	;If text is ref'ed by ptr or offset, this is validJust	ds.w  1	;Initial justification word to be passed to LETextBox2RecordSize	ENDR;-----------------------------------------------------------;; This is the template for LineEdit controls;LineEditTemplate	RECORD  0pCount	ds.w  1	;parameter count (8 or 9 or 10)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;LineEditControl = $83000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;new flag wordRefCon	ds.l  1	;application definedMaxLen	ds.w  1	;maximum length of input lineIVRef	ds.l  1	;Reference to initial valuePasswordChar	ds.w  1	;Password Character (added 11-Mar-91 DAL)keyMask	ds.w  1	;Mask (added 23-Mar-92 DAL)RecordSize	ENDR;-----------------------------------------------------------;; This is the template for Picture controls.;PictureTemplate	RECORD  0pCount	ds.w  1	;parameter count (7)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;PictureControl = $8D000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedPicRef	ds.l  1	;handle or resourceRecordSize	ENDR;-----------------------------------------------------------;; This is the template for Scroll Controls;ScrollTemplate	RECORD  0pCount	ds.w  1	;parameter count (8 or 9)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;ScrollControl = $86000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedDataSize	ds.w  1	;amount of data represented by the scroll barViewSize	ds.w  1	;amount of data seen at one timeInitialThumb	ds.w  1	;initial setting of the thumb.ColorRef	ds.l  1	;Reference to color tableRecordSize	ENDR;-----------------------------------------------------------;; This is the template for Grow Controls;GrowTemplate	RECORD  0pCount	ds.w  1	;parameter count (6 or 7)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;GrowControl = $88000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;bit 0 refers to PicRef (0 handle, 1 resource)RefCon	ds.l  1	;application definedColorRef	ds.l  1	;Reference to color tableRecordSize	ENDR;-----------------------------------------------------------;; This is the template for List Controls;ListTemplate	RECORD  0pCount	ds.w  1	;parameter count (14 or 15)ID	ds.l  1	;ID for the control Rect	ds.w  4	;bounding rectangleProcRef	ds.l  1	;ListControl = $89000000Flag	ds.w  1	;old style flag wordMoreFlags	ds.w  1	;RefCon	ds.l  1	;application definedListSize	ds.w  1	;num members in listListView	ds.w  1	;num members seen at one timeListType	ds.w  1	;multi-selections, pascal strings etcListStart	ds.w  1	;First member to be seenListDraw	ds.l  1	;member drawing routineListMemHeight	ds.w  1	;height of each itemListMemSize	ds.w  1	;num bytes in list recordListRef	ds.l  1	;ref to list of member recordsColorRef	ds.l  1	;Reference to color tableRecordSize	ENDRSuperCtlSize	equ  NewCtlRecord.RecordSize